import { useEffect, useMemo, useState } from "react";

export default function Reviews() {
  const [reviews, setReviews] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [editingId, setEditingId] = useState(null);
  const [editMessage, setEditMessage] = useState("");
  const [editRating, setEditRating] = useState(5);

  // ================= FETCH REVIEWS =================
  const fetchReviews = async () => {
    try {
      const token = localStorage.getItem("adminToken");

      if (!token) {
        setError("Admin not authenticated");
        setLoading(false);
        return;
      }

      const res = await fetch("http://localhost:5001/admin/reviews", {
        headers: { Authorization: "Bearer " + token },
      });

      if (!res.ok) throw new Error("Failed to fetch reviews");

      const data = await res.json();
      if (Array.isArray(data)) {
        // Sort descending by created_at (most recent first)
        const sorted = data.sort(
          (a, b) => new Date(b.created_at) - new Date(a.created_at)
        );
        setReviews(sorted);
      } else {
        setReviews([]);
      }
    } catch (err) {
      console.error("❌ Reviews load error:", err);
      setError("Failed to load reviews");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchReviews();
  }, []);

  // ================= UPDATE STATUS =================
  const updateStatus = async (id, status) => {
    try {
      const token = localStorage.getItem("adminToken");
      if (!token) return;

      const res = await fetch(
        `http://localhost:5001/admin/reviews/${id}`,
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
            Authorization: "Bearer " + token,
          },
          body: JSON.stringify({ status }),
        }
      );

      if (!res.ok) throw new Error("Status update failed");

      setReviews((prev) =>
        prev.map((r) => (r.id === id ? { ...r, status } : r))
      );
    } catch (err) {
      console.error("❌ Status update error:", err);
    }
  };

  // ================= START EDIT =================
  const startEdit = (review) => {
    setEditingId(review.id);
    setEditMessage(review.message);
    setEditRating(review.rating);
  };

  // ================= SAVE UPDATE =================
  const saveUpdate = async (id) => {
    try {
      const token = localStorage.getItem("adminToken");
      if (!token) return;

      const res = await fetch(`http://localhost:5001/admin/reviews/${id}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          Authorization: "Bearer " + token,
        },
        body: JSON.stringify({
          message: editMessage,
          rating: editRating,
        }),
      });

      if (!res.ok) throw new Error("Update failed");

      setReviews((prev) =>
        prev.map((r) =>
          r.id === id
            ? { ...r, message: editMessage, rating: editRating }
            : r
        )
      );
      setEditingId(null);
    } catch (err) {
      console.error("❌ Review update error:", err);
    }
  };

  // ================= ANALYTICS =================
  const analytics = useMemo(() => {
    if (!reviews.length) return null;

    const activeReviews = reviews.filter((r) => r.status === "Active");
    const total = activeReviews.length;
    const avgRating =
      total === 0
        ? 0
        : (
            activeReviews.reduce((sum, r) => sum + r.rating, 0) / total
          ).toFixed(1);

    const distribution = [5, 4, 3, 2, 1].map((star) => {
      return {
        star,
        count: activeReviews.filter((r) => r.rating === star).length,
      };
    });

    return { total, avgRating, distribution };
  }, [reviews]);

  // ================= RECENT 6 REVIEWS =================
  const recentReviews = useMemo(() => reviews.slice(0, 6), [reviews]);

  // ================= UI =================
  return (
    <div className="p-10 text-white">
      <h1 className="text-3xl font-bold text-yellow-400 mb-6">
        Customer Reviews Analytics
      </h1>

      {/* ANALYTICS CARD */}
      {analytics && (
        <div className="grid md:grid-cols-3 gap-6 mb-12">
          {/* Avg Rating */}
          <div className="bg-gradient-to-br from-[#111] to-[#0b0b0b] p-6 rounded-2xl border border-yellow-500/20 flex flex-col items-center shadow-lg">
            <span className="text-gray-400 text-sm">Average Rating</span>
            <span className="text-yellow-400 text-4xl font-bold mt-2">
              {analytics.avgRating} ★
            </span>
          </div>

          {/* Total Reviews */}
          <div className="bg-gradient-to-br from-[#111] to-[#0b0b0b] p-6 rounded-2xl border border-yellow-500/20 flex flex-col items-center shadow-lg">
            <span className="text-gray-400 text-sm">Total Reviews</span>
            <span className="text-yellow-400 text-4xl font-bold mt-2">
              {analytics.total}
            </span>
          </div>

          {/* Rating Distribution */}
          <div className="bg-gradient-to-br from-[#111] to-[#0b0b0b] p-6 rounded-2xl border border-yellow-500/20 shadow-lg">
            <span className="text-gray-400 text-sm mb-2 block">
              Rating Distribution
            </span>
            <div className="space-y-1">
              {analytics.distribution.map((d) => (
                <div key={d.star} className="flex items-center gap-2">
                  <span className="text-yellow-400 font-semibold w-4">
                    {d.star}★
                  </span>
                  <div className="flex-1 h-2 bg-gray-700 rounded-full relative overflow-hidden">
                    <div
                      className="h-2 bg-yellow-400 absolute left-0 top-0"
                      style={{
                        width: `${
                          analytics.total === 0
                            ? 0
                            : (d.count / analytics.total) * 100
                        }%`,
                      }}
                    ></div>
                  </div>
                  <span className="text-gray-400 text-sm w-6 text-right">
                    {d.count}
                  </span>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* RECENT REVIEWS */}
      <h2 className="text-2xl font-semibold text-yellow-400 mb-6">
        Recent Reviews
      </h2>

      {loading ? (
        <p className="text-gray-400">Loading reviews...</p>
      ) : error ? (
        <p className="text-red-400">{error}</p>
      ) : recentReviews.length === 0 ? (
        <p className="text-gray-500">No reviews found</p>
      ) : (
        <div className="space-y-6 max-w-5xl">
          {recentReviews.map((review) => (
            <div
              key={review.id}
              className="bg-gradient-to-br from-[#0b0b0b] to-[#111]
                         border border-yellow-500/30 rounded-2xl p-6 shadow-xl"
            >
              {/* HEADER */}
              <div className="flex justify-between items-center mb-3">
                <h2 className="text-lg font-semibold text-yellow-400">
                  {review.name}
                </h2>

                <span
                  className={`text-xs px-3 py-1 rounded-full font-semibold ${
                    review.status === "Active"
                      ? "bg-green-500/20 text-green-400"
                      : "bg-red-500/20 text-red-400"
                  }`}
                >
                  {review.status}
                </span>
              </div>

              {/* EDIT MODE */}
              {editingId === review.id ? (
                <>
                  <select
                    value={editRating}
                    onChange={(e) =>
                      setEditRating(Number(e.target.value))
                    }
                    className="mb-3 bg-black border border-yellow-500 rounded px-3 py-1 text-white"
                  >
                    {[1, 2, 3, 4, 5].map((n) => (
                      <option key={n} value={n}>
                        {n} Star
                      </option>
                    ))}
                  </select>

                  <textarea
                    value={editMessage}
                    onChange={(e) =>
                      setEditMessage(e.target.value)
                    }
                    className="w-full bg-black border border-yellow-500 rounded p-3 text-sm text-white mb-3"
                    rows={3}
                  />

                  <div className="flex gap-3">
                    <button
                      onClick={() => saveUpdate(review.id)}
                      className="bg-yellow-400 text-black px-4 py-1 rounded-lg font-semibold"
                    >
                      Save
                    </button>

                    <button
                      onClick={() => setEditingId(null)}
                      className="bg-gray-600 text-white px-4 py-1 rounded-lg"
                    >
                      Cancel
                    </button>
                  </div>
                </>
              ) : (
                <>
                  {/* RATING */}
                  <div className="flex items-center mb-3">
                    {[1, 2, 3, 4, 5].map((n) => (
                      <span
                        key={n}
                        className={
                          n <= review.rating
                            ? "text-yellow-400 text-lg"
                            : "text-gray-600 text-lg"
                        }
                      >
                        ★
                      </span>
                    ))}
                  </div>

                  {/* MESSAGE */}
                  <p className="text-gray-300 text-sm mb-4">
                    {review.message}
                  </p>

                  {/* DATE */}
                  <p className="text-xs text-gray-500 mb-4">
                    {new Date(review.created_at).toLocaleString()}
                  </p>

                  {/* ACTIONS */}
                  <div className="flex gap-3 flex-wrap">
                    <button
                      onClick={() => startEdit(review)}
                      className="bg-blue-500 text-black px-4 py-1 rounded-lg font-semibold"
                    >
                      Update
                    </button>

                    {review.status !== "Active" && (
                      <button
                        onClick={() =>
                          updateStatus(review.id, "Active")
                        }
                        className="bg-green-500 text-black px-4 py-1 rounded-lg font-semibold"
                      >
                        Approve
                      </button>
                    )}

                    {review.status !== "Hidden" && (
                      <button
                        onClick={() =>
                          updateStatus(review.id, "Hidden")
                        }
                        className="bg-red-500 text-black px-4 py-1 rounded-lg font-semibold"
                      >
                        Hide
                      </button>
                    )}
                  </div>
                </>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
